INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 1, 'theory', 'Квиз: что такое Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 0, 'Что означает, что Rust — компилируемый язык?', '["Программу читает интерпретатор при каждом запуске","Компилятор заранее превращает код в машинные команды и выдаёт исполняемый файл","Программа работает только внутри браузера","Код нельзя запустить без интернета"]', 1, 'Компилятор rustc проверяет типы и память и создаёт файл с машинными командами. Запускать его можно без Rust.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 1, 'Какую главную проблему решает Rust?', '["Медленный интерфейс","Нехватку библиотек","Длинные названия функций","Ошибки с памятью (выход за границы, использование освобождённой памяти, гонки данных) — запрещая их при сборке"]', 3, 'По оценкам Microsoft и Chromium, около 70% серьёзных уязвимостей связаны с памятью. Rust убирает этот класс ошибок без сборщика мусора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 2, 'Когда вышла стабильная версия Rust 1.0?', '["В 2006 году","В 2021 году","15 мая 2015 года","В 2022 году"]', 2, 'В 2006 году начался личный проект Грейдона Хора, с 2009 его поддерживала Mozilla, а 1.0 вышла 15 мая 2015. С тех пор версии выходят каждые шесть недель.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 3, 'Что делает команда cargo run?', '["Только проверяет синтаксис","Собирает проект и запускает программу","Устанавливает компилятор","Удаляет проект"]', 1, 'cargo build только собирает, cargo check проверяет без создания файла, cargo new создаёт проект, а cargo run собирает и запускает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 4, 'Что значит восклицательный знак в println!?', '["Ошибку","Громкий вывод","Конец строки","Что это макрос, а не обычная функция"]', 3, 'Макросы раскрываются при компиляции и могут принимать переменное число аргументов. println! подставляет значения в {} и печатает строку с переводом строки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 2, 'theory', 'Квиз: переменные');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 0, 'Что произойдёт при let x = 5; x = 6;?', '["x станет равен 6","Ошибка компиляции: переменная неизменяема, нужен mut","Паника во время работы","Значение останется 5 без ошибки"]', 1, 'По умолчанию переменные неизменяемы. Добавьте mut: let mut x = 5; тогда присвоение разрешено.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 1, 'В чём разница между let mut x и затенением let x = x + 1?', '["mut меняет значение на месте и сохраняет тип; затенение создаёт новую переменную и может сменить тип","Разницы нет","Затенение работает только с числами","mut нельзя использовать в функциях"]', 0, 'Затенение — это новое объявление с let; старая переменная закрыта. Так можно превратить строку в число под тем же именем.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 2, 'Что нужно обязательно указывать у const?', '["Ничего","Слово mut","Тип значения","Имя в нижнем регистре"]', 2, 'const MAX: u32 = 100; — тип обязателен, значение вычисляется при компиляции, а имя принято писать ЗАГЛАВНЫМИ_БУКВАМИ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 3, 'Можно ли записать строку в переменную x: i32?', '["Да, как в Python","Да, если переменная mut","Только в блоке","Нет: тип переменной не меняется — ошибка mismatched types"]', 3, 'Rust статически типизирован: тип известен при сборке и не меняется. Новый тип получают затенением через let.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 2, 4, 'Где живёт переменная, объявленная внутри блока { … }?', '["До конца программы","От объявления до закрывающей фигурной скобки блока","Только в одной строке","Пока её не затенили"]', 1, 'Область видимости ограничена блоком; на выходе переменная уничтожается.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 3, 'theory', 'Квиз: типы данных');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 0, 'Какой тип получит переменная в let n = 7;?', '["i64","usize","i32","u8"]', 2, 'Без подсказок целые выводятся как i32, а дробные — как f64.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 1, 'Что даст 7 / 2 для целых чисел?', '["3.5","3","4","ошибку компиляции"]', 1, 'Деление целых отбрасывает дробную часть. Чтобы получить 3.5, хотя бы одно число должно быть дробным: 7.0 / 2.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 2, 'Что произойдёт при сборке в режиме debug, если к u8 со значением 255 прибавить 1?', '["паника из-за переполнения","результат станет 0 без сообщений","результат станет 256","ошибка компиляции всегда"]', 0, 'В debug переполнение — паника; в release значение обернётся. Чтобы поведение не зависело от режима, берите checked_add, wrapping_add или saturating_add.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 3, 'Что нужно написать, чтобы сложить a: i32 и b: i64?', '["просто a + b","a + b as i32 нельзя — это невозможно","поставить mut","привести один из операндов: i64::from(a) + b"]', 3, 'Rust не смешивает числовые типы автоматически: преобразуйте явно — через From, as или try_from.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 3, 4, 'Почему в Rust нельзя написать if 1 { … }?', '["потому что 1 — не число","условие обязано быть типа bool — «истинности» чисел нет","из-за ограничений компилятора","потому что if принимает только строки"]', 1, 'Условие — только bool: пишите явное сравнение, например if n != 0.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 4, 'theory', 'Квиз: функции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 0, 'Как вернуть значение из функции в конце тела в идиоматичном Rust?', '["написать последнее выражение без точки с запятой","return значение; в последней строке","присвоить значение переменной result","вызвать exit(значение)"]', 0, 'Последнее выражение без ; становится результатом. return оставляют для раннего выхода.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 1, 'Что скажет компилятор о fn f() -> i32 { 5; }?', '["всё в порядке, вернётся 5","ожидался i32, найден (): точка с запятой превратила выражение в инструкцию","функция вернёт None","нужно написать return"]', 1, 'Точка с запятой отбрасывает значение; блок без итогового выражения имеет тип ().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 2, 'Что возвращает функция без стрелки -> ?', '["ничего: значения нет вообще","None","ошибку компиляции","() — юнит, значение пустого типа"]', 3, 'Тип () — единственное значение которого тоже (); именно его возвращают fn main и println!.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 3, 'Как вернуть из функции сразу два числа?', '["вернуть два return подряд","передать два результата через глобальные переменные","вернуть кортеж: -> (i32, i32)","так нельзя"]', 2, 'Кортеж — составное значение из нескольких элементов: let (a, b) = f();');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 4, 4, 'Можно ли в Rust задать значение параметра по умолчанию, как в Python def f(a, b=1)?', '["нет, в Rust таких параметров нет","да, через знак равно в сигнатуре","да, но только для чисел","только в макросах"]', 0, 'Необязательных параметров нет: вместо них пишут отдельные функции или используют Option и структуры.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 5, 'theory', 'Квиз: условия и циклы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 0, 'Какие числа перебирает for i in 1..4?', '["1, 2, 3, 4","1, 2, 3","0, 1, 2, 3","2, 3, 4"]', 1, 'Правая граница не входит. Чтобы включить 4, напишите 1..=4.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 1, 'Что произойдёт при if x { … }, где x: i32?', '["сработает, если x не нуль","сработает, если x больше нуля","ошибка компиляции: условие должно быть bool","сработает всегда"]', 2, 'В Rust нет «истинных» чисел; пишите явное сравнение: if x != 0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 2, 'Для чего можно использовать break значение; внутри loop?', '["чтобы выйти и вернуть значение как результат всего цикла","чтобы продолжить цикл с новым значением","чтобы вывести значение на экран","так нельзя, break не принимает значение"]', 0, 'let r = loop { … break 42; }; — цикл становится выражением.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 3, 'Что делает метка ''outer: for … вместе с break ''outer;?', '["пропускает один шаг цикла","ничего, это комментарий","делает цикл бесконечным","выходит сразу из внешнего цикла"]', 3, 'Метки нужны, чтобы выйти из вложенных циклов одной командой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 5, 4, 'Что произойдёт, если в match по u8 не рассмотреть все значения и не добавить _?', '["программа напечатает предупреждение","ошибка компиляции: образцы не исчерпывающие","на лишних значениях сработает первая ветка","паника во время выполнения"]', 1, 'match обязан покрыть все варианты; для остальных пишут _ => …');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 6, 'theory', 'Квиз: строки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 0, 'Что вернёт "привет".len()?', '["6","12","2","ошибку: len для строк нет"]', 1, 'len считает байты в UTF-8: каждая русская буква занимает 2 байта. Число символов даёт chars().count().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 1, 'Почему нельзя написать s[0] для строки?', '["индексов в Rust нет вообще","это слишком медленно","индекс — только для String, а не &str","символ может занимать несколько байтов, и индекс попал бы в его середину"]', 3, 'Берите n-й символ через s.chars().nth(n) или срезайте по границам символов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 2, 'Чем отличается String от &str?', '["String во владении программы и может расти, &str — ссылка на чужой текст","ничем, это синонимы","&str можно менять, String — нет","String хранится только в стеке"]', 0, 'String живёт в куче и меняется (push_str); &str — только чтение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 3, 'Как склеить два текста, не потеряв ни один?', '["s1 + s2","s1 += s2 всегда работает для &str","формат: format!(\"{}{}\", s1, s2)","вызвать join у числа"]', 2, 'format! ничего не забирает и работает как f-строка. Оператор + забирает левую строку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 4, 'Что делает "1, 2, 3".split('','') ?', '["возвращает вектор чисел","возвращает итератор по кускам «1», « 2», « 3»","сразу меняет исходную строку","вызывает панику"]', 1, 'split возвращает итератор по подстрокам; чтобы получить числа, добавьте trim, parse и collect.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 7, 'theory', 'Квиз: кортежи, массивы, векторы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 0, 'Что произойдёт при a[5] для массива из трёх элементов, если индекс неизвестен при сборке?', '["вернётся 0","вернётся случайное значение из памяти","паника при выполнении: индекс вне границ","элемент будет создан автоматически"]', 2, 'Rust проверяет границы при каждом обращении. Безопасная альтернатива — a.get(5), который вернёт None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 1, 'Что входит в тип массива [i32; 3]?', '["только i32","тип элементов и длина 3","только длина","способ хранения в куче"]', 1, 'Длина — часть типа: [i32; 3] и [i32; 4] — разные типы. У вектора длина в тип не входит.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 2, 'Как получить значение последнего элемента вектора v, которое может не существовать?', '["v[-1]","v.last() — вернёт Option","v.end()","v[v.len()]"]', 1, 'Отрицательных индексов нет. last() возвращает Some(&x) или None для пустого вектора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 3, 'Для чего функциям удобно принимать параметр типа &[i32]?', '["чтобы изменять вектор","чтобы быстрее работал цикл","потому что только срезы можно передавать","в такую функцию можно передать и массив, и вектор, и часть вектора"]', 3, 'Срез — ссылка на часть последовательности. &arr, &vec и &vec[1..] — все подойдут.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 4, 'Что нужно, чтобы вызвать v.push(4)?', '["объявить вектор как let mut v","ничего: push работает всегда","вектор должен быть массивом","вызвать v.clone()"]', 0, 'Методы изменения требуют изменяемого вектора: let mut v = vec![…];');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 8, 'theory', 'Квиз: структуры и перечисления');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 0, 'Что означает &self в первом параметре метода?', '["метод забирает экземпляр целиком","метод только читает данные экземпляра","метод создаёт новый экземпляр","метод вызывается без объекта"]', 1, '&self — ссылка для чтения; &mut self — для изменения; self — забирает владение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 1, 'Как получить из структуры нужное поле?', '["через точку: u.name","через квадратные скобки: u[\"name\"]","через ключ: u->name","только через метод"]', 0, 'Поля читаются через точку; для кортежных структур — по номеру: c.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 2, 'Что делает компилятор, если вы забыли обработать один из вариантов enum в match?', '["ничего, по умолчанию выберет первый","пропускает и вернёт ()","выдаст ошибку: образцы не исчерпывающие","сгенерирует ветку _ сам"]', 2, 'match обязан покрыть все варианты — так добавление варианта подсвечивает все места, которые надо обновить.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 3, 'Чем Option лучше null?', '["значение, которого может не быть, видно в типе, и его нельзя использовать, не проверив","он работает быстрее","он хранит больше данных","его можно использовать как обычное значение"]', 0, 'Some(x) или None — компилятор заставляет проверить. «Миллиардную ошибку» с null здесь сделать нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 4, 'Что вернёт "abc".parse::<i32>()?', '["паника","0","None","Err(…) — значение типа Result"]', 3, 'parse возвращает Result: Ok(число) или Err(ошибка разбора). unwrap остановит программу при Err.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 9, 'theory', 'Квиз: типы Python и Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 0, 'Что даст −7 / 2 для целых в Rust?', '["−4, как в Python","−3: деление округляет к нулю","−3.5","ошибку компиляции"]', 1, 'Python округляет вниз (−4), Rust — к нулю (−3); остаток −7 % 2 в Rust равен −1. Для питоновского поведения есть div_euclid и rem_euclid.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 1, 'Как устроен список из миллиона чисел в Python по сравнению с Vec<i32> в Rust?', '["список — указатели на отдельные объекты, вектор — числа подряд в памяти","обе структуры хранят числа подряд","в Rust вектор хранит указатели, в Python — числа","разницы нет"]', 0, 'Из-за этого вектор лучше работает с кэшем процессора и занимает в разы меньше памяти.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 2, 'Что нужно сделать, чтобы сложить i32 и f64?', '["просто сложить: Rust приведёт сам","объявить обе переменные mut","привести явно: a as f64 + b","использовать оператор ++"]', 2, 'Rust не смешивает числовые типы автоматически — преобразование всегда явное.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 3, 'Чем отличается присваивание b = a для String в Rust от b = a для списка в Python?', '["ничем","в Rust оно создаёт глубокую копию","в Rust a и b указывают на один объект","в Rust оно перемещает владение, и a становится недоступной"]', 3, 'Python копирует ссылку, и оба имени видят один объект. Rust перемещает значение, чтобы не было двух владельцев.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 4, 'Что произойдёт при очень глубокой рекурсии в Rust?', '["переполнение стека — аварийное завершение","RecursionError, который можно поймать","программа замедлится, но продолжит","компилятор заменит рекурсию циклом"]', 0, 'У главного потока ~8 МБ стека; при переполнении программа аварийно завершается. Глубокие обходы лучше писать циклом.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 10, 'theory', 'Квиз: def и fn');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 0, 'Как в Rust заменяют параметр со значением по умолчанию (def f(x=5))?', '["пишут fn f(x = 5)","принимают Option и подставляют unwrap_or, либо делают структуру со значениями","это невозможно, и обойти нельзя","пишут fn f(x?: i32)"]', 1, 'У параметров нет значений по умолчанию: используют Option, несколько функций или шаблон «строитель».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 1, 'Чем заменить *args из Python?', '["макросом vararg!","ничем: Rust не умеет принимать много значений","параметром-срезом &[T] или вектором","ключевым словом rest"]', 2, 'Функция принимает &[i32]: в неё можно передать массив, вектор или часть вектора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 2, 'Что понимает Rust в записи 1 < x < 10?', '["проверку диапазона","ничего: это ошибка, нужно x > 1 && x < 10 или (2..10).contains(&x)","проверку на равенство","сравнение первого и последнего"]', 1, 'Цепочек сравнений в Rust нет; пишите условия явно через && или диапазон.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 3, 'Чем в Rust заменяют исключения Python?', '["макросом try!","блоком catch","ничем, ошибки игнорируются","типом Result и оператором ?; для неисправимого — panic!"]', 3, 'Функция сама говорит в типе Result о возможной ошибке, а ? передаёт её вызывающей функции.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 10, 4, 'Во что превращается включение списка [x*2 for x in v if x>0]?', '["v.iter().filter(|x| **x > 0).map(|x| x * 2).collect()","for-цикл с ключевым словом yield","макрос list![…]","в Rust такого нельзя"]', 0, 'Цепочка итераторов компилируется в обычный цикл без промежуточных коллекций.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 11, 'theory', 'Квиз: строки Python и Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 0, 'Что вернёт метод find у строки в Rust, если подстроки нет?', '["-1, как в Python","0","None — значение типа Option<usize>","панику"]', 2, 'Option не позволяет спутать «нет подстроки» с позицией; в Python легко забыть проверку на -1.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 1, 'Чем заменить Python-вызов " ".join(words)?', '["words.join(\" \")","join(words, \" \")","words.concat(\" \")","String::join(\" \", words)"]', 0, 'join вызывается на срезе или векторе строк, разделитель — аргумент.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 2, 'Что возвращает from_utf8 для набора байтов?', '["сразу String","Option<String>","Vec<char>","Result<String, _> — байты могут быть не UTF-8"]', 3, 'Для данных из неизвестных источников есть from_utf8_lossy, который подменяет неверные байты специальным символом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 3, 'Почему "straße".to_uppercase() может быть длиннее исходной строки?', '["это ошибка языка","потому что к строке добавляется нулевой байт","при смене регистра «ß» превращается в «SS»","to_uppercase всегда удваивает строку"]', 2, 'Преобразование регистра по правилам Unicode — на уровне символа может дать несколько символов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 11, 4, 'Что нужно для подсчёта «видимых» символов с эмодзи и составными знаками?', '["метод chars().count()","метод len()","ничего, std всё умеет","графемные кластеры — пакет unicode-segmentation"]', 3, 'chars() считает кодовые точки, а не графемы; в std графем нет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 12, 'theory', 'Квиз: список и вектор');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 0, 'Что произойдёт при удалении элементов из вектора внутри for x in &v?', '["программа не соберётся: вектор уже заимствован циклом","всё сработает, как в Python","элементы будут пропускаться","паника во время выполнения"]', 0, 'Компилятор запрещает изменять вектор, пока по нему идёт обход. Используйте retain, drain или соберите новый вектор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 1, 'Чем заменяют l.pop(i) из Python?', '["v.pop(i)","v.delete(i)","v.remove(i) — возвращает удалённый элемент","v.take(i)"]', 2, 'pop() без аргументов у вектора тоже есть, но возвращает Option; pop(i) — это remove(i).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 2, 'Чем отличается срез l[1:3] в Python от &v[1..3] в Rust?', '["ничем","оба — ссылки на часть списка","в Rust срез копирует, в Python — нет","в Python срез — копия, в Rust — ссылка на часть вектора"]', 3, 'Срез Rust не копирует данные: ничего не выделяется и не копируется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 3, 'Как в Rust сделать независимую копию вектора, включая вложенные элементы?', '["let b = a;","a.clone()","let b = &a;","a.copy()"]', 1, 'clone делает глубокую копию; присваивание перемещает владение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 4, 'Какой тип подходит для очереди с быстрым добавлением в конец и забором из начала?', '["Vec","VecDeque","[T; N]","BinaryHeap"]', 1, 'VecDeque — аналог collections.deque. Забор из начала Vec стоит линейного времени.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 13, 'theory', 'Квиз: классы и трейты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 0, 'Чем в Rust заменяют наследование из Python?', '["макросом extends!","композицией (структура внутри структуры) и трейтами","ключевым словом super","ничем: наследование есть"]', 1, 'Структуры не наследуются: общее поведение выносят в трейт, а данные собирают композицией.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 1, 'Что нужно реализовать, чтобы работал оператор + для своего типа?', '["метод __add__","макрос operator!","ничего: плюс работает всегда","трейт std::ops::Add"]', 3, 'Операторы — это трейты из std::ops; результат записывают в ассоциированном типе Output.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 2, 'Что соответствует __str__ из Python?', '["fmt::Display","PartialEq","Iterator","Debug, выведенный через derive"]', 0, 'Display — вывод для пользователя ({}), Debug — для отладки ({:?}); реализовав Display, получаете to_string().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 3, 'Как положить в один вектор значения разных структур, реализующих один трейт?', '["Vec<impl Trait>","Vec<Trait>","Vec<Box<dyn Trait>>","Vec<enum>, и больше никак"]', 2, 'Трейт-объекты dyn вызываются через таблицу методов, поэтому типы могут различаться.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 13, 4, 'Зачем нужен шаблон newtype?', '["чтобы реализовать чужой трейт для чужого типа через собственную обёртку","чтобы наследовать поля","чтобы ускорить компиляцию","чтобы копировать значения"]', 0, 'Правило согласованности запрещает чужой трейт для чужого типа; обёртка с одним полем — своя, и трейт реализовать можно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 14, 'theory', 'Квиз: словарь и HashMap');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 0, 'Что вернёт m.get(&k) для отсутствующего ключа?', '["панику","0","None — значение типа Option","Err"]', 2, 'get возвращает Option<&V>; в Python d[k] бросило бы KeyError, а d.get(k) — None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 1, 'Как в Rust записывают подсчёт слов в стиле Counter?', '["m[w] += 1","*m.entry(w).or_insert(0) += 1","m.count(w)","m.insert(w, m[w] + 1)"]', 1, 'entry().or_insert(0) возвращает &mut значения; звёздочка раскрывает ссылку. Поиск по ключу один.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 2, 'Можно ли полагаться на порядок обхода HashMap, как на порядок вставки в dict Python?', '["да, порядок вставки сохраняется","да, порядок по возрастанию ключей","только для строковых ключей","нет, порядок произволен и может меняться между запусками"]', 3, 'Нужен порядок — отсортируйте ключи, возьмите BTreeMap или пакет indexmap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 3, 'Что происходит с ключом-строкой после m.insert(k, 1)?', '["ключ перемещён в карту: k больше недоступна","ничего, k можно использовать дальше","k копируется автоматически","ключ превращается в &str"]', 0, 'insert забирает владение. Если ключ нужен дальше, передайте k.clone().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 14, 4, 'Какие методы выдают объединение и пересечение множеств?', '["plus и times","merge и cut","union и intersection","or и and"]', 2, 'a.union(&b), a.intersection(&b), a.difference(&b) возвращают итераторы, которые собирают в новое множество.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 15, 'theory', 'Квиз: владение');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 0, 'Что произойдёт после let t = s;, если s — это String?', '["Обе переменные указывают на один буфер и обе остаются доступны","Три слова s копируются в t, а s становится недействительной","Строка копируется целиком в новый буфер","Программа соберётся, но упадёт при запуске"]', 1, 'Присваивание переносит владение: на стеке копируются указатель, длина и ёмкость, а имя s использовать нельзя. Иначе на скобке буфер освободили бы дважды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 1, 'Какой из этих типов можно скопировать побитно (он реализует Copy)?', '["String","Vec<i32>","Box<i32>","(i32, f64, char)"]', 3, 'Copy доступен тем, кто целиком лежит на стеке и ничем не владеет в куче: числа, bool, char и кортежи или массивы из них. String, Vec и Box владеют кучей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 2, 'В каком порядке уничтожаются переменные блока на закрывающей скобке?', '["В обратном порядке объявления","В порядке объявления","В произвольном порядке","Все сразу, порядок не определён"]', 0, 'Последняя созданная умирает первой, как кадры на стеке. Поэтому зависимые значения можно создавать позже тех, от кого они зависят.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 3, 'Зачем нужен Box в определении enum List { Cons(i32, Box<List>), Nil }?', '["Чтобы список работал быстрее","Чтобы значения можно было копировать","Чтобы размер типа стал конечным: внутри лежит указатель, а не сам List","Чтобы элементы удалялись сборщиком мусора"]', 2, 'Без Box тип содержал бы себя и имел бесконечный размер (ошибка E0072). Указатель занимает 8 байт, а продолжение цепочки лежит в куче.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 4, 'Что делает Rc::clone(&a)?', '["Копирует значение в новый буфер","Копирует указатель и увеличивает счётчик владельцев","Переносит владение и обнуляет a","Создаёт слабую ссылку без счётчика"]', 1, 'Данные не дублируются: появляется ещё один владелец того же значения, strong_count растёт на единицу. Значение уничтожится, когда уйдёт последний владелец.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 16, 'theory', 'Квиз: заимствование и ссылки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 0, 'Сколько читателей (&T) может одновременно существовать у одного значения, если писателей нет?', '["Ровно один","Два","Сколько угодно","Столько, сколько ядер у процессора"]', 2, 'Пока никто не пишет, читатели друг другу не мешают — как несколько ядер, держащих строку кэша в состоянии Shared. Ограничение появляется только с писателем.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 1, 'Что делает проверщик займов с таким кодом: let first = &v[0]; v.push(4); println!("{first}");?', '["Компилирует: push всегда безопасен","Компилирует, но паникует при запуске","Автоматически клонирует вектор","Отказывается компилировать: заём first ещё нужен, а push может переместить буфер"]', 3, 'push способен выделить новый буфер и освободить старый — first повис бы в пустоте. Раст запрещает менять вектор, пока читатель жив, и ловит это при сборке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 2, 'Почему функция fn make() -> &String { let s = String::new(); &s } не компилируется?', '["Потому что ссылка пережила бы кадр функции и значение, которое в нём уничтожается","Потому что String нельзя создавать внутри функции","Потому что нужно написать &mut","Потому что функции нельзя возвращать ссылки"]', 0, 'Кадр исчезает при возврате, s уничтожается — ссылка указывала бы в мёртвую зону. Исправление: вернуть String, то есть передать владение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 3, 'Из чего состоит срез &str или &[T] и сколько он занимает на 64-битной машине?', '["Только указатель, 8 байт","Указатель и длина, 16 байт","Копия данных, размер зависит от среза","Указатель, длина и ёмкость, 24 байта"]', 1, 'Срез не владеет данными: это адрес начала и количество элементов. Ёмкость есть только у String и Vec, которые владеют буфером.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 4, 'Что означает аннотация времени жизни в fn longest<''a>(a: &''a str, b: &''a str) -> &''a str?', '["Во время работы программа проверяет, что ссылки ещё живы","Функция копирует строки на время вызова","Результат не переживёт ни один из аргументов — это проверяется компилятором, а во время работы аннотации нет","Результат всегда указывает на a"]', 2, 'Параметры времени жизни — подсказки для проверщика займов: они связывают ссылки в подписи и стираются при сборке, ничего не стоя во время работы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 17, 'theory', 'Квиз: структуры, перечисления и match');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 0, 'Что значит для перечисления Shape { Circle(f64), Rect(f64, f64), Point }, что оно «тип-сумма»?', '["Все варианты хранятся одновременно","Варианты складываются арифметически","Значение в любой момент находится ровно в одном варианте со своими данными","Варианты наследуют друг друга"]', 2, 'Структура — произведение (все поля сразу), перечисление — сумма (один вариант из нескольких). В памяти это тег плюс общее место под самую большую нагрузку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 1, 'Что произойдёт, если в match по enum забыть один из вариантов и не поставить _?', '["Компилятор откажется собирать программу: образцы не исчерпывают варианты","Ветвь для забытого варианта выполнится по умолчанию","Программа упадёт паникой при запуске на этом варианте","Забытый вариант будет молча пропущен"]', 0, 'Исчерпываемость проверяется при сборке (ошибка E0004). Добавив новый вариант в enum, вы получите список всех мест, которые нужно обновить.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 2, 'Почему Option<Box<i32>> занимает столько же, сколько Box<i32>?', '["Потому что Option — это просто синоним Box","Потому что компилятор сжимает данные","Потому что Option хранит значение в куче","Потому что None кодируется нулевым указателем, а у настоящего Box адрес никогда не нулевой — тег не нужен"]', 3, 'Это ниша: неиспользуемое значение указателя отдаётся под None. А у Option<u32> ниши нет, и размер возрастает до восьми байт (тег плюс выравнивание).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 3, 'Что делает match opt { Some(s) => …, None => … } по значению для opt: Option<String>?', '["Копирует строку в s и оставляет opt нетронутым","Перемещает строку в s: после match переменная opt (целиком) недоступна","Только читает строку, не меняя владельца","Паникует, если opt — Some"]', 1, 'Привязка по значению переносит владение, как обычное присваивание. Нужно сохранить opt — разбирайте ссылку: match &opt.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 4, 'В каком порядке derive(PartialOrd, Ord) сравнивает поля структуры?', '["По алфавиту имён полей","По размеру полей","В порядке записи полей в определении, лексикографически","Случайно, порядок не определён"]', 2, 'Порядок полей в определении становится порядком сравнения — поэтому перестановка строк в struct может изменить сортировку.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 18, 'theory', 'Квиз: коллекции и ошибки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 0, 'Что хранит на стеке Vec<i32>?', '["Все элементы подряд","Только указатель","Таблицу хеш-значений","Указатель на буфер, длину и ёмкость — три слова"]', 3, 'Сами элементы лежат в куче, подряд и без заголовков. Когда ёмкость кончается, push выделяет буфер вдвое больше и переносит туда элементы — вставка амортизированно стоит константу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 1, 'Что делает *map.entry(word).or_insert(0) += 1?', '["Создаёт новую запись при каждом вызове, затирая старую","Находит ячейку по ключу, кладёт 0 если её нет, и увеличивает счётчик через &mut","Паникует, если слова нет","Копирует всю таблицу"]', 1, 'entry — один поиск по хешу; or_insert возвращает изменяемую ссылку на значение, поэтому счётчик увеличивается на месте.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 2, 'Что делает оператор ? в функции, возвращающей Result<T, E>, если выражение вернуло Err?', '["Паникует","Игнорирует ошибку и продолжает","Немедленно возвращает Err из функции, преобразуя ошибку через From","Выводит сообщение и завершает процесс"]', 2, '? разворачивает Ok в значение, а на Err возвращает ошибку наружу; если типы ошибок отличаются, вызывается From::from.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 3, 'Что происходит с лежащими в кадрах значениями при панике (panic = unwind)?', '["Стек разматывается, и для значений вызывается drop","Ничего: память просто бросается","Они копируются в куче","Программа сразу прекращается, как после abort"]', 0, 'Раст идёт вверх по кадрам и вызывает drop: файлы закрываются, блокировки отпускаются. Процесс завершается с кодом 101, если панику не поймали.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 18, 4, 'Когда сработает collect::<Result<Vec<i32>, _>>() над итератором результатов разбора строк?', '["Вернёт Ok со всеми успешными числами, пропуская ошибки","Остановится на первой ошибке и вернёт её","Паникует при любой ошибке","Вернёт вектор, а ошибки отбросит"]', 1, 'Если все элементы Ok — получите Ok(Vec). При первой же ошибке сборка прекращается и возвращается этот Err. Чтобы отбросить неудачные, используют filter_map(Result::ok).');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 19, 'theory', 'Квиз: трейты и обобщённые типы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 0, 'Что произойдёт в fn largest<T>(v: &[T]) -> &T, если сравнить два элемента через >, не добавив ограничение?', '["Программа соберётся, а упадёт при запуске","Компилятор сам подставит PartialOrd","Ошибка компиляции: для T не известно, что он сравним","Сравнение будет по адресам"]', 2, 'Операции над параметром типа разрешены только те, что гарантирует ограничение. T: PartialOrd сообщает компилятору, что сравнение определено.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 1, 'Что делает мономорфизация обобщённой функции?', '["Создаёт при сборке отдельную копию функции для каждого использованного типа","Выбирает нужную версию во время работы через таблицу","Приводит все типы к одному","Отключает проверки типов"]', 0, 'Во время работы нет накладных расходов, вызовы прямые и встраиваются; цена — размер программы и время сборки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 2, 'Из чего состоит значение типа Box<dyn Shape> на стеке?', '["Из данных фигуры целиком","Из одного указателя на данные","Из имени типа строкой","Из двух указателей: на данные и на таблицу виртуальных методов (16 байт)"]', 3, 'Толстый указатель хранит адрес данных и адрес vtable с drop, размером, выравниванием и методами; вызов идёт косвенно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 3, 'Какое утверждение о правиле сироты верно?', '["Можно реализовать любой трейт для любого типа","Нельзя реализовать чужой трейт для чужого типа — нужно владеть хотя бы одним","Трейты можно реализовать только внутри того же файла","Правило касается только дженериков"]', 1, 'Правило запрещает двум библиотекам реализовать один чужой трейт для одного чужого типа по-разному и тем самым ломать совместимость.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 4, 'Чем ассоциированный тип Item в Iterator отличается от обобщённого параметра трейта?', '["Ничем","Ассоциированный тип доступен только внутри функции","У типа может быть только одна реализация Iterator, поэтому тип элемента один и его не повторяют в каждой сигнатуре","Он вычисляется во время работы"]', 2, 'Для каждой реализации ассоциированный тип фиксирован. Обобщённый параметр позволил бы несколько реализаций одного трейта для одного типа.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 20, 'theory', 'Квиз: замыкания и итераторы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 0, 'Каким трейтом обладает замыкание, которое возвращает захваченную String (move || s)?', '["FnOnce: вызвать можно только один раз","Fn","FnMut","Все три"]', 0, 'Замыкание, потребляющее захваченное значение, можно вызвать лишь однажды: после этого значение отдано. Fn и FnMut получают те, что только читают или меняют окружение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 1, 'Что делает цепочка v.iter().map(|x| x * 2).filter(|x| x > 4) без потребителя в конце?', '["Вычисляет все значения и выбрасывает","Ошибка компиляции","Ничего не вычисляет: только строит ленивый конвейер","Создаёт новый вектор"]', 2, 'Адаптеры ленивы. Работу запускает потребитель — sum, collect, count, for. Компилятор предупредит о неиспользованном итераторе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 2, 'Что означает слово move перед замыканием?', '["Замыкание переедет в другую функцию","Замыкание станет FnOnce","Замыкание выполнится в другом потоке","Замыкание заберёт захваченные переменные во владение, а не возьмёт ссылки"]', 3, 'move меняет способ захвата: значения переходят в замыкание. Это нужно, чтобы замыкание переживало функцию или уходило в поток.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 3, 'Почему в filter(|x| ...) по v.iter() приходится писать **x или |&&x|?', '["Это особенность синтаксиса","iter() выдаёт &T, а filter передаёт ещё одну ссылку на элемент — получается &&T","Потому что x — указатель на функцию","Так требует Fn"]', 1, 'filter не должен забирать элемент, поэтому даёт &Item, а Item у iter() уже ссылка. Образец |&&x| разбирает обе ссылки сразу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 20, 4, 'Почему цепочка адаптеров работает так же быстро, как ручной цикл?', '["Потому что компилятор запускает её в отдельных потоках","Потому что результат кешируется","Потому что каждый адаптер — структура с известным типом, и вызовы замыканий встраиваются в один цикл","Это неправда: цепочка медленнее"]', 2, 'Нет промежуточных списков и косвенных вызовов: компилятор видит всю цепочку и склеивает её, а сумму часто векторизует.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 21, 'theory', 'Квиз: время жизни и умные указатели');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 0, 'Что делает Rc::clone(&a)?', '["Копирует данные в новую область кучи","Переносит владение и обнуляет a","Увеличивает сильный счётчик, данные остаются общими","Создаёт слабую ссылку"]', 2, 'Клон Rc дёшев: меняется только счётчик. Значение уничтожится, когда счётчик станет нулём.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 1, 'Когда программа с RefCell паникует?', '["Когда вызван borrow() на пустом значении","Когда одновременно существуют две изменяемые ссылки или изменяемая и разделяемая","Когда значение слишком большое","Никогда"]', 1, 'RefCell проверяет правила заимствования при запуске: нарушение даёт BorrowMutError. try_borrow_mut() вернёт Err вместо паники.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 2, 'Зачем в дереве ссылку на родителя делают Weak, а не Rc?', '["Чтобы не получить цикл Rc, из-за которого счётчики не станут нулевыми","Чтобы экономить память","Чтобы можно было менять родителя","Потому что Weak быстрее"]', 0, 'Родитель держит детей сильными ссылками, а ребёнок родителя — слабой. Тогда цикла нет, и узлы освобождаются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 3, 'Чем Arc отличается от Rc?', '["Ничем","Арк хранит значение в стеке","Счётчик Arc меняется атомарными командами, поэтому его можно делить между потоками, но он медленнее","Rc можно отправлять в потоки"]', 2, 'Rc не реализует Send и в другой поток не уйдёт. Arc платит за атомарность скоростью и трафиком кэша.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 4, 'Что вернёт функция fn pick(a: &str, b: &str) -> &str без меток времени жизни?', '["Ссылку на a","Ошибку компиляции: непонятно, к какому аргументу привязан результат","Ссылку на b","Новую строку"]', 1, 'Правила пропуска не разрешают выбор между двумя входами. Нужна метка: fn pick<''a>(a: &''a str, b: &''a str) -> &''a str.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 22, 'theory', 'Квиз: модули, тесты и cargo');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 0, 'Что означает отсутствие слова pub перед функцией в модуле?', '["Функция открыта всем","Функция видна только в своём модуле и его дочерних модулях","Функция видна во всём крейте","Функция не компилируется"]', 1, 'В расте всё закрыто по умолчанию. pub(crate) открывает в пределах крейта, pub — наружу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 1, 'Зачем нужен файл Cargo.lock?', '["Хранить документацию","Блокировать параллельные сборки","Описывать features","Фиксировать точные версии зависимостей, чтобы сборки были воспроизводимыми"]', 3, 'В Cargo.toml указаны диапазоны совместимости, а lock запоминает конкретный выбор вместе с контрольными суммами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 2, 'Чем интеграционные тесты в папке tests/ отличаются от модульных?', '["Ничем","Они быстрее","Каждый файл — отдельный крейт, который видит только pub-интерфейс библиотеки","Они видят закрытые функции"]', 2, 'Модульный тест — дочерний модуль и видит закрытое, а интеграционный подключает библиотеку как внешний пользователь.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 3, 'Что делает pub use в lib.rs?', '["Экспортирует элемент под коротким публичным путём, оставляя внутреннюю структуру закрытой","Подключает чужой крейт","Делает модуль публичным целиком","Отключает проверку видимости"]', 0, 'Реэкспорт формирует публичный интерфейс: пользователь не зависит от внутренней раскладки файлов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 4, 'Как проверить, что ваши тесты вообще способны найти ошибку?', '["Запустить их несколько раз","Увеличить число assert","Включить режим release","Нарочно сломать реализацию и убедиться, что хотя бы один тест падает"]', 3, 'Это мутационное тестирование. Тест, который зелёный и на сломанном коде, ничего не проверяет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 23, 'theory', 'Квиз: потоки и общее состояние');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 0, 'Почему Rc<T> нельзя передать в другой поток?', '["Потому что Rc слишком большой","Потому что Rc нельзя клонировать","Это возможно, нужен только move","Потому что счётчик Rc меняется неатомарно — два потока его испортят; Rc не Send"]', 3, 'Компилятор проверяет маркерный трейт Send: thread::spawn требует его от замыкания. Для потоков берут Arc с атомарным счётчиком.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 1, 'Что произойдёт с блокировкой Mutex при выходе охранника из области видимости?', '["Ничего: нужно вызвать unlock","Сработает drop охранника и замок отпустится сам","Замок останется навсегда","Поток будет завершён"]', 1, 'RAII: охранник освобождает мьютекс в Drop. Забыть отпустить замок нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 2, 'В чём главная идея разделить-и-слить для параллельных вычислений?', '["Все потоки пишут в общую переменную под мьютексом","Потоки по очереди обрабатывают данные","Каждый поток обрабатывает свой кусок и накапливает результат у себя, а потом результаты объединяются","Данные копируются во все потоки"]', 2, 'Нет общей записи — нет ожидания на замке и передвижения строк кэша между ядрами; результат не зависит от порядка выполнения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 3, 'Что гарантирует закон Амдала?', '["Что ускорение ограничено долей последовательной работы","Что ускорение растёт линейно с числом ядер","Что число потоков равно числу ядер","Что мьютекс медленнее атомика"]', 0, 'Если 10% программы нельзя распараллелить, быстрее чем в десять раз не станет, сколько ядер ни добавляй.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 4, 'Как избежать взаимной блокировки двух мьютексов?', '["Брать оба замка одновременно в любом порядке","Использовать Relaxed","Всегда захватывать блокировки в одном и том же порядке во всех потоках","Увеличить число потоков"]', 2, 'Если у всех потоков один порядок захвата, цикла ожидания не возникнет. Помогает и try_lock с откатом.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 24, 'theory', 'Квиз: обзор стандартной библиотеки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 0, 'Какой слой стандартной библиотеки содержит Vec и String, но не требует операционной системы?', '["core","alloc","std","prelude"]', 1, 'alloc добавляет к core всё, что требует кучи; std — ещё и ОС.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 1, 'Что означает префикс into_ в имени метода?', '["метод забирает владение значением","метод возвращает ссылку","метод проверяет условие","метод изменяет значение на месте"]', 0, 'into_iter, into_boxed_slice забирают значение; as_ — дешёвая ссылка; to_ — новое значение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 2, 'Как вынуть значение из поля &mut self, оставив вместо него пустое?', '["let x = self.field;","self.field.clone().drop()","std::mem::forget(self.field)","std::mem::take(&mut self.field)"]', 3, 'mem::take забирает значение и оставляет Default; mem::replace — подставляет своё.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 3, 'Что делает Option::ok_or(err)?', '["превращает Result в Option","вызывает панику с сообщением err","превращает Option в Result, подставляя ошибку для None","возвращает значение по умолчанию"]', 2, 'Some(x) становится Ok(x), None — Err(err); дальше можно использовать ?.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 24, 4, 'Почему «не найден метод» иногда означает не отсутствие метода?', '["потому что метод скрыт в документации","потому что трейт с этим методом не подключён через use","потому что компилятор устарел","потому что метод приватный всегда"]', 1, 'Методы трейтов видны, только если трейт в области видимости (прелюдия или use).');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 25, 'theory', 'Квиз: коллекции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 0, 'Какая коллекция подходит для очереди с добавлением в конец и забором из начала?', '["VecDeque","Vec","BinaryHeap","HashSet"]', 0, 'VecDeque — кольцевой буфер: push_back и pop_front за O(1). Забор из начала Vec — O(n).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 1, 'Как получить кучу-минимум из BinaryHeap?', '["BinaryHeap::min()","вызвать sort() у кучи","нельзя: куча всегда максимум","обернуть значения в Reverse"]', 3, 'BinaryHeap<Reverse<T>> выдаёт наименьшее первым.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 2, 'Что вернёт swap_remove у Vec?', '["удалит элемент и сдвинет хвост","поменяет два элемента местами","удалит элемент за O(1), подставив на его место последний","вернёт None"]', 2, 'swap_remove не сохраняет порядок, зато стоит O(1).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 3, 'Когда следует предпочесть BTreeMap, а не HashMap?', '["всегда, он быстрее","когда нужны порядок ключей и запросы по диапазонам","когда ключи — числа","когда нет ограничения памяти"]', 1, 'BTreeMap обходит ключи по возрастанию и умеет range, first_key_value, pop_first.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 25, 4, 'Почему документация советует Vec и VecDeque вместо LinkedList?', '["список не поддерживает итераторы","список не может хранить числа","в списке нет метода push","узлы списка разбросаны по куче — много промахов кэша"]', 3, 'Из-за локальности данных Vec и VecDeque на практике быстрее даже там, где у списка лучше асимптотика.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 26, 'theory', 'Квиз: текст и форматирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 0, 'Что делает "k=v".split_once(''='')?', '["возвращает итератор с двумя элементами","делит по первому вхождению и возвращает Option<(&str, &str)>","возвращает пару String","вызывает панику, если знака нет"]', 1, 'split_once удобен для разбора «ключ=значение»; при отсутствии разделителя вернёт None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 1, 'Что означает спецификатор {:>8.2}?', '["выравнивание влево, 8 знаков","ширина 2, точность 8","выравнивание вправо в поле шириной 8, два знака после запятой","вывод в шестнадцатеричной системе"]', 2, '> — вправо, 8 — ширина, .2 — точность для дробных чисел.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 2, 'Чем отличается Display от Debug?', '["ничем","Debug работает только для чисел","Display нельзя использовать с println!","Display — для пользователя ({}), пишется вручную; Debug — для программиста ({:?}), чаще через derive"]', 3, 'Два разных трейта: красивый вывод для людей и отладочный вывод для разработчиков.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 3, 'Что вернёт "0x1f".parse::<i32>()?', '["Err: префикс 0x парс не понимает","Ok(31)","Ok(0)","панику"]', 0, 'Префикс нужно убрать и вызвать i32::from_str_radix("1f", 16).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 26, 4, 'Что принимают split, trim_matches и find в качестве шаблона?', '["только &str","только char","char, &str, массив символов или замыкание, возвращающее bool","только регулярные выражения"]', 2, 'Трейт Pattern реализован для всех этих типов — регулярки для простых задач не нужны.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 27, 'theory', 'Квиз: ввод-вывод');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 0, 'Зачем оборачивать файл в BufReader при построчном чтении?', '["чтобы получить доступ к lines(); сам File его не имеет, и чтобы сократить число системных вызовов","чтобы читать быстрее без буферов","чтобы файл закрывался вручную","чтобы читать только байты"]', 0, 'BufReader читает крупными блоками: меньше системных вызовов; BufRead добавляет read_line и lines().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 1, 'Что вернёт read, если достигнут конец потока?', '["Err(UnexpectedEof)","None","Ok(0)","панику"]', 2, 'Ok(0) означает конец потока; read_exact в такой ситуации вернёт ошибку UnexpectedEof.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 2, 'Как проще всего протестировать функцию, читающую из R: BufRead?', '["создать временный файл и читать его","передать Cursor::new(\"…\") — данные в памяти","нельзя, нужен настоящий stdin","переопределить stdin глобально"]', 1, 'Cursor реализует Read и BufRead: тесты не касаются диска.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 3, 'Чем Path отличается от PathBuf?', '["Path — для Windows, PathBuf — для Linux","ничем","Path нельзя печатать","Path — ссылка (как &str), PathBuf — владеющий (как String)"]', 3, 'Они не обязаны быть Unicode; для печати — path.display().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 27, 4, 'Что делает flush?', '["закрывает файл","доводит буферизованные данные до приёмника","очищает содержимое файла","ничего, это пустой метод"]', 1, 'После print! без перевода строки нужен flush(), иначе приглашение может не появиться; BufWriter сбрасывает буфер и при drop.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 28, 'theory', 'Квиз: время, числа, память');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 0, 'Чем замерять время работы участка кода?', '["SystemTime::now()","Instant::now() и elapsed()","thread::sleep","Duration::default()"]', 1, 'Instant монотонен и не зависит от переводов часов; SystemTime может скакать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 1, 'Что произойдёт при Wrapping(255u8) + Wrapping(1)?', '["паника","ошибка компиляции","получится Wrapping(0) даже в режиме debug","Wrapping(256)"]', 2, 'Wrapping делает оборот частью поведения; Saturating упирается в границу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 2, 'Почему Option<NonZeroU32> занимает 4 байта?', '["компилятор сжимает числа","ноль освобождён для None — ниша","потому что u32 не нужен","это ошибка в документации"]', 1, 'Нулевое значение NonZero невозможно, и компилятор использует его для None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 3, 'Что вернёт Duration::from_secs(1).checked_sub(Duration::from_secs(2))?', '["отрицательную длительность","Duration::ZERO","панику","None"]', 3, 'Отрицательных длительностей нет: checked_sub возвращает None, saturating_sub — ноль.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 28, 4, 'Где в экосистеме Rust искать случайные числа?', '["пакет rand","std::random","std::num","только в операционной системе"]', 0, 'В std нет генератора случайных чисел; обычно используют пакет rand.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 29, 'theory', 'Квиз: трейты std');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 0, 'Почему f64 реализует PartialEq и PartialOrd, но не Eq и Ord?', '["потому что дробные числа слишком большие","из-за NaN: он не равен даже самому себе и несравним","потому что у f64 нет значения по умолчанию","потому что f64 копируется"]', 1, 'Eq и Ord требуют полного равенства и порядка; NaN их нарушает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 1, 'Что получается автоматически, если реализовать From<A> for B?', '["Into<B> for A","TryFrom<B> for A","Clone для B","Default для B"]', 0, 'Into для A реализуется сам: пишите From, пользуйтесь into().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 2, 'Какой трейт замыканий самый строгий (требует больше всего от замыкания)?', '["FnOnce","FnMut","Fn","они равны"]', 2, 'Fn — только читает и вызывается много раз; такое замыкание подходит и под FnMut, и под FnOnce.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 3, 'Что гарантирует согласованность Hash и Eq?', '["разные значения дают разные хеши","хеш не зависит от значения","хеш всегда равен нулю","равные значения дают одинаковый хеш"]', 3, 'Иначе HashMap не найдёт ключ, который лежит в ней.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 29, 4, 'Почему Rc<T> не Send?', '["потому что T может быть строкой","потому что счётчик ссылок у Rc не атомарный","потому что Rc хранит ссылки","потому что Rc нельзя копировать"]', 1, 'Для потоков есть Arc с атомарным счётчиком.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 30, 'theory', 'Квиз: асинхронность в Python и Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 0, 'Что происходит при вызове async fn в Rust без .await и без передачи рантайму?', '["функция выполняется сразу","создаётся Future, тело не выполнено — ничего не происходит","ошибка компиляции","функция запускается в отдельном потоке"]', 1, 'Future ленив: тело выполняется только при poll, который делает исполнитель.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 1, 'Чем в Rust заменяют asyncio.gather?', '["макросом join! (или try_join!)","функцией sleep","методом cancel","оператором ?"]', 0, 'join! ждёт все фьючеры и возвращает кортеж результатов; try_join! останавливается на первой ошибке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 2, 'Где находится цикл событий в Rust?', '["в стандартной библиотеке","в компиляторе","в библиотеке-рантайме, например tokio","в операционной системе"]', 2, 'В std есть только Future, Poll, Context, Waker; цикл, таймеры и сеть приносит рантайм.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 3, 'Что нужно делать с блокирующим кодом внутри async-задачи tokio?', '["ничего, tokio сам справится","отправить в spawn_blocking","добавить await после него","обернуть в async-блок"]', 1, 'Блокирующий вызов занимает рабочий поток; spawn_blocking отправляет его в отдельный пул.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 4, 'Что происходит с фьючером, который отбросили (drop) до завершения?', '["доработает в фоне","вызовет панику","вернёт None","остановится на ближайшем .await, значения освободятся деструкторами"]', 3, 'Отмена в Rust — это просто уничтожение; поэтому код должен выдерживать остановку между любыми двумя .await.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 31, 'theory', 'Квиз: Future, Poll, Waker');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 0, 'Что обязан сделать фьючер перед тем, как вернуть Poll::Pending?', '["ничего особенного","обеспечить, чтобы waker был вызван позже, когда есть что проверять","вызвать drop у себя","заблокировать поток"]', 1, 'Иначе исполнитель никогда не опросит задачу снова — она зависнет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 1, 'Для чего нужен Context в методе poll?', '["хранит результат","хранит стек вызовов","даёт доступ к Waker текущей задачи","задаёт приоритет"]', 2, 'cx.waker() — дескриптор, который нужно сохранить или вызвать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 2, 'Что делает thread::park в простом block_on?', '["усыпляет поток до unpark, который вызовет waker","завершает поток","ждёт ввод пользователя","меняет приоритет"]', 0, 'Так поток не жжёт процессор в цикле опроса.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 3, 'Почему сохраняют самый свежий waker при каждом poll?', '["потому что старый всегда неверен","потому что Waker нельзя клонировать","для ускорения компиляции","потому что задачу могли передать другому исполнителю, и разбудить нужно новый дескриптор"]', 3, 'Контракт Future допускает смену waker между опросами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 4, 'Во что компилятор превращает async fn с двумя точками .await?', '["в два потока","в конечный автомат — enum с несколькими состояниями","в замыкание","в вызов sleep"]', 1, 'Размер фьючера определяется самым большим из состояний.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 32, 'theory', 'Квиз: async, await и Pin');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 0, 'Что определяет размер фьючера async-блока?', '["число строк в блоке","самый большой набор значений, живых через .await","число вызовов функции","размер стека потока"]', 1, 'В каждом состоянии хранятся только переменные, живые после точки .await; размер — максимум по состояниям.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 1, 'Для чего нужен Pin?', '["чтобы значение, на которое могут ссылаться его же поля, не перемещалось","для ускорения","для шифрования","для передачи между потоками"]', 0, 'Автомат async может ссылаться сам на себя; перемещение сделало бы такие ссылки недействительными.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 2, 'Почему tokio::spawn не принимает ссылку на локальную переменную родителя?', '["потому что ссылки запрещены в Rust","потому что ссылки не Send","задача требует ''static: родитель может завершиться раньше","это ошибка компилятора"]', 2, 'Передавайте владение: move, Arc::clone, каналы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 3, 'Как написать рекурсивную async-функцию?', '["обычным вызовом самой себя","через thread::spawn","нельзя в Rust","упаковать рекурсивный вызов: Box::pin(f(n - 1)).await"]', 3, 'Без Box::pin размер автомата включал бы сам себя бесконечно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 32, 4, 'Что делает фьючер !Send при использовании std::sync::Mutex?', '["ничего","удерживаемый через .await MutexGuard не реализует Send","Mutex запрещён в async","Mutex делает фьючер медленным"]', 1, 'Освободите страж до .await, используйте tokio::sync::Mutex или не держите замок через ожидание.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 33, 'theory', 'Квиз: tokio — рантайм и spawn');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 0, 'Что возвращает tokio::spawn?', '["результат фьючера сразу","JoinHandle<T>","Future без запуска","поток ОС"]', 1, 'Задача запускается сразу; .await хэндла даёт Result<T, JoinError>.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 1, 'Что произойдёт с задачей, если в ней случится паника?', '["паника изолирована: хэндл вернёт JoinError с is_panic()","упадёт весь рантайм","программа завершится","паника игнорируется без следов"]', 0, 'Рантайм продолжает работу; ошибка приходит ожидающему результат.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 2, 'Куда отправить блокирующий вызов, чтобы не занять рабочий поток?', '["в tokio::spawn","в join!","в yield_now","в spawn_blocking"]', 3, 'Замыкание из spawn_blocking выполняется в отдельном пуле потоков.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 3, 'Что происходит с незавершёнными задачами, когда main вернула управление?', '["рантайм ждёт их","они продолжают в фоне","они отменяются: рантайм уничтожен","программа зависает"]', 2, 'Ждите важные задачи явно через JoinHandle или JoinSet.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 33, 4, 'Для чего нужен LocalSet и spawn_local?', '["для запуска Send-задач быстрее","для задач, не являющихся Send, на одном потоке","для блокирующего кода","для таймеров"]', 1, 'Они решают ошибку «future is not Send», когда задача не должна менять поток.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 34, 'theory', 'Квиз: tokio — время и select!');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 0, 'Чем tokio::time::sleep отличается от std::thread::sleep внутри async-задачи?', '["Ничем","sleep возвращает фьючер и отдаёт поток другим задачам, а thread::sleep блокирует поток","thread::sleep точнее","sleep работает только в тестах"]', 1, 'Блокирующий sleep усыпляет поток вместе со всеми задачами на нём. Токиошный sleep освобождает поток на время ожидания.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 1, 'Когда срабатывает первый tick() у tokio::time::interval?', '["Через один период","Сразу, без ожидания","После второго вызова","Никогда: нужен reset"]', 1, 'Первый тик интервала возвращается немедленно, дальше — через постоянный период.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 2, 'Что вернёт timeout(d, fut), если фьючер не уложился в d?', '["Ok(None)","Err(Elapsed), а фьючер отбрасывается","Паника","Значение по умолчанию"]', 1, 'Результат — Err(Elapsed); выполнение внутреннего фьючера прекращается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 3, 'Что происходит с проигравшими ветками select!?', '["Они продолжают работать в фоне","Их фьючеры отбрасываются (drop)","Они выполняются позже по очереди","Они вызывают панику"]', 1, 'Победителем становится первый завершившийся фьючер, остальные отбрасываются — отсюда требование безопасности к отмене.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 4, 'Зачем нужен biased; в начале select!?', '["Для ускорения","Чтобы ветки опрашивались строго по порядку, а не случайно","Чтобы включить логирование","Чтобы отключить else"]', 1, 'По умолчанию порядок опроса случаен ради честности. biased; делает порядок детерминированным.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 35, 'theory', 'Квиз: tokio — каналы и синхронизация');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 0, 'Что вернёт rx.recv().await, когда все Sender уничтожены и канал пуст?', '["Err","None","Паника","Вечное ожидание"]', 1, 'Закрытый и опустошённый mpsc-канал возвращает None — так цикл приёма сам завершается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 1, 'Что происходит с send().await в ограниченном канале при полном буфере?', '["Сообщение теряется","Задача ждёт, пока освободится место","Возвращается ошибка","Буфер удваивается"]', 1, 'send ждёт: так медленный потребитель замедляет производителя — это backpressure. try_send вместо ожидания сразу вернёт ошибку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 2, 'Для чего удобен oneshot в паттерне «запрос — ответ»?', '["Для рассылки всем подписчикам","Отправитель oneshot вкладывают в сообщение, а рабочая задача отвечает по нему","Для ограничения числа задач","Для хранения последнего значения"]', 1, 'oneshot передаёт ровно одно значение: идеально для ответа на конкретный запрос.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 3, 'Чем tokio::sync::Mutex отличается от std::sync::Mutex?', '["Ничем","Его охранник можно держать через .await, а lock() асинхронный","Он работает быстрее при коротких секциях","Он не требует Arc"]', 1, 'Охранник std-мьютекса нельзя держать через .await в spawn-задаче (он не Send). Токиошный можно, но он медленнее.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 4, 'Что делает Semaphore::new(3)?', '["Создаёт три потока","Разрешает одновременно не более трёх держателей разрешений","Создаёт канал на три сообщения","Запускает три задачи"]', 1, 'Семафор хранит число разрешений: acquire ждёт свободное, а пока охранник жив, разрешение занято.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 36, 'theory', 'Квиз: tokio — сеть и ввод-вывод');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 0, 'Что означает, что read() вернул 0?', '["Данных пока нет","Собеседник закрыл соединение: конец потока","Произошла ошибка","Буфер пуст"]', 1, 'Ноль байт — признак конца потока (EOF). Отсутствие данных выражается ожиданием, а не нулём.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 1, 'Почему одним read() нельзя гарантированно получить сообщение целиком?', '["Размер буфера ограничен 1 байтом","TCP — поток байт без границ сообщений: данные могут прийти порциями","read работает только в блокирующем режиме","Сокет всегда читает по одному байту"]', 1, 'Границы сообщений в TCP не сохраняются: нужны префикс длины или разделитель, либо read_exact для известной длины.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 2, 'Для чего служит into_split()?', '["Для разделения файла на части","Для получения читающей и пишущей половин сокета с владением, чтобы отдать их разным задачам","Для создания двух соединений","Для сжатия данных"]', 1, 'into_split возвращает OwnedReadHalf и OwnedWriteHalf; их можно переместить в разные задачи.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 3, 'Как сообщить собеседнику «я закончил отправку», но продолжить читать ответ?', '["Уничтожить весь сокет","Вызвать shutdown() у пишущей половины","Отправить пустое сообщение","Закрыть программу"]', 1, 'shutdown закрывает только запись: собеседник получает EOF, а читающая половина остаётся открытой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 36, 4, 'Чем UdpSocket отличается от TcpStream?', '["Ничем","Нет соединения: отдельные датаграммы с сохранением границ, без гарантий доставки и порядка","UDP надёжнее TCP","UDP работает только внутри одной машины"]', 1, 'UDP передаёт независимые датаграммы: границы сохраняются, но потери, повторы и перестановки возможны.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 37, 'theory', 'Квиз: tokio на практике');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 0, 'Что происходит с кодом после .await, когда задачу отменили методом abort()?', '["Он выполняется до конца","Он не выполняется: фьючер больше не опрашивается, локальные значения уничтожаются","Выполняется только первый оператор","Задача перезапускается"]', 1, 'Отмена в async — это отбрасывание фьючера; код после ближайшего .await не выполнится, а Drop локальных переменных сработает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 1, 'Что делает отмена родительского CancellationToken?', '["Ничего","Отменяет и всех детей, созданных child_token()","Только родителя","Паникует"]', 1, 'Отмена родителя каскадно отменяет дочерние токены; отмена ребёнка на родителя не влияет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 2, 'Как правильно делать очистку, требующую .await, при завершении?', '["Вызвать .await внутри Drop","Вынести её в явный async-метод закрытия, вызываемый при штатном завершении","Использовать unsafe","Очистка невозможна"]', 1, 'Drop синхронный: в нём нельзя ждать. Медленную очистку делают явным async-методом, а в Drop оставляют только быстрые действия.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 3, 'Что лучше сделать с запросом, когда очередь переполнена?', '["Принять и ждать бесконечно","Быстро отказать (сброс нагрузки), сохранив отзывчивость для принятых","Удвоить очередь","Закрыть сервер"]', 1, 'Быстрый отказ не копит задачи и память; принятые запросы продолжают обслуживаться вовремя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 4, 'Как запустить тяжёлое блокирующее вычисление, не замораживая рабочие потоки tokio?', '["Прямо в async fn","tokio::task::spawn_blocking","std::thread::sleep","Через select!"]', 1, 'spawn_blocking выполняет работу в отдельном пуле потоков, а задача ждёт результат через .await.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 38, 'theory', 'Квиз: алгоритмы на Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 0, 'Почему середину в бинарном поиске считают как lo + (hi - lo) / 2?', '["Так быстрее","Сумма lo + hi может переполниться на больших индексах","Так требует компилятор","Чтобы округлять вверх"]', 1, 'Форма lo + (hi - lo) / 2 безопасна для любых допустимых границ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 1, 'Как получить минимальную кучу из std::collections::BinaryHeap?', '["Вызвать метод min_heap()","Обернуть элементы в std::cmp::Reverse","Отсортировать вектор","Нельзя"]', 1, 'BinaryHeap — максимальная куча; Reverse переворачивает порядок сравнения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 2, 'Чем опасно 3usize - 5?', '["Ничем, получится -2","У usize нет знака: в debug — паника, в release — огромное число; нужны checked_sub / saturating_sub","Не скомпилируется","Результат 0"]', 1, 'Выбирайте явную операцию: проверяющую, насыщающую, оборачивающую или переполняющуюся.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 3, 'Что хранит массив расстояний Vec<Option<u32>> в обходе в ширину?', '["Только достижимые вершины","Some(расстояние) для достигнутых и None для недостижимых","Номера родителей","Веса рёбер"]', 1, 'Option естественно кодирует «ещё не посещена / недостижима».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 4, 'Что даёт сжатие путей в системе непересекающихся множеств?', '["Уменьшает память","Перенаправляет пройденные вершины на корень — последующие поиски почти мгновенны","Сортирует элементы","Удаляет циклы в графе"]', 1, 'Вместе с объединением по размеру это даёт почти константное амортизированное время.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 39, 'theory', 'Квиз: биты, байты и эмулятор');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 0, 'Чему равно 300i32 as u8 в Rust?', '["300","255","44","паника"]', 2, 'Сужение отбрасывает старшие биты: 300 mod 256 = 44.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 1, 'Как в Rust записать число в байты в сетевом порядке (старший первым)?', '["n.to_le_bytes()","n.to_be_bytes()","n.as_bytes()","n.swap()"]', 1, 'be — big-endian; порядок явно указан в имени метода.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 2, 'Почему структура { u8, u32, u8 } в Rust обычно занимает 8 байт, а с #[repr(C)] — 12?', '["Ошибка компилятора","Rust вправе переставлять поля, чтобы уменьшить выравнивание; repr(C) фиксирует порядок как в C","repr(C) сжимает данные","Это зависит от ОС"]', 1, 'Каждое поле выравнивается по своему типу; перестановка убирает пустые байты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 3, 'Что хранит старший бит байта в varint (LEB128)?', '["Знак числа","Признак продолжения: есть ли следующий байт","Контрольную сумму","Ничего"]', 1, 'Остальные семь бит — порции числа, поэтому малые значения занимают один байт.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 39, 4, 'Почему в эмуляторе ошибки доступа к памяти возвращают Result<_, Trap>, а не паникуют?', '["Это быстрее","Неправильная программа — не ошибка эмулятора: она должна вызвать «прерывание», а эмулятор — продолжить работать","Паника запрещена","Result нельзя использовать в циклах"]', 1, 'Так эмулятор ведёт себя как настоящий процессор: сообщает о ловушке, а не падает.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 40, 'theory', 'Квиз: файлы, процессы и сокеты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 0, 'Зачем буферизованный писатель (BufWriter) нужно сбрасывать или дать ему уничтожиться?', '["Чтобы освободить имя файла","Иначе последние накопленные в буфере данные могут не дойти до файла","Чтобы сменить кодировку","Это нужно только для сокетов"]', 1, 'Буфер копит записи и отправляет реже — ради меньшего числа системных вызовов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 1, 'Как правильно сопоставлять ошибку открытия файла?', '["По тексту сообщения","По e.kind(): ErrorKind::NotFound, PermissionDenied и т. д.","Через unwrap","По коду выхода процесса"]', 1, 'Вид ошибки не зависит от языка сообщения и платформы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 2, 'Почему аргументы Command передают списком, а не одной строкой?', '["Так быстрее","Нет разбора шеллом: нельзя внедрить лишнюю команду пробелом или кавычкой","Так требует Windows","Для экономии памяти"]', 1, 'Command не запускает шелл — аргументы доходят программе ровно как переданы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 3, 'Почему при записи в stdin дочернего процесса важно закрыть этот вход?', '["Это освобождает память","Программа (например, sort) узнаёт, что данных больше не будет, иначе ждёт вечно","Иначе вывод будет в другой кодировке","Это необязательно"]', 1, 'Закрытие канала — это конец файла для читающей стороны.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 40, 4, 'Что означает порт 0 при bind?', '["Запрещённый порт","Система выберет любой свободный; номер можно узнать через local_addr()","Порт по умолчанию 80","Широковещательный адрес"]', 1, 'Удобно для тестов и примеров: не нужно заранее договариваться о номере порта.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 41, 'theory', 'Квиз: HTTP по байтам');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 0, 'Чем в HTTP заголовки отделяются от тела?', '["Символом ;","Пустой строкой (\\r\\n\\r\\n)","Заголовком Body:","Длиной в первой строке"]', 1, 'После последнего заголовка идёт пустая строка, дальше — тело (если есть).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 1, 'В чём считают значение Content-Length?', '["В символах","В байтах","В строках","В килобайтах"]', 1, '«привет» в UTF-8 — 12 байт: ошибка в длине ломает соединение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 2, 'Почему сервер должен ограничивать размер заголовков и тела?', '["Для красоты","Иначе клиент заставит выделить гигабайты памяти","Так требует TCP","Для шифрования"]', 1, 'Любое значение, пришедшее от клиента, — недоверенное: нужны пределы и таймауты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 3, 'Что такое обход каталогов (path traversal) и как с ним бороться?', '["Быстрый перебор файлов","Адрес с ../ выводит за корень раздачи; пропускайте только обычные компоненты пути","Сжатие путей","Кэширование каталогов"]', 1, 'Нельзя просто приклеивать путь из запроса к корню — нужно проверять компоненты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 41, 4, 'Что означает код ответа 405?', '["Файл не найден","Метод запроса не поддерживается для этого пути","Слишком большое тело","Внутренняя ошибка"]', 1, '404 — нет пути; 405 — путь есть, но метод для него недопустим.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 42, 'theory', 'Квиз: маршрутизатор и многопоточный сервер');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 0, 'Когда маршрутизатор должен ответить 405, а не 404?', '["Когда путь содержит ошибку","Когда нашёлся шаблон пути, но для него нет запрошенного метода","Когда тело слишком большое","Когда сервер перегружен"]', 1, '404 — такого ресурса нет вообще; 405 — ресурс есть, но метод для него недопустим.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 1, 'Почему конкретный маршрут /users/new нужно регистрировать раньше /users/:id?', '["Так быстрее","Приоритет определяет порядок записей: иначе «new» будет принято за значение :id","Это требует компилятор","Иначе не скомпилируется"]', 1, 'Побеждает первая подошедшая запись.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 2, 'Как реализуется мягкая остановка пула потоков?', '["Принудительным убийством потоков","Закрытием передатчика очереди: рабочие дорабатывают принятые задания и выходят, а Drop ждёт их через join","Паникой в потоках","Остановкой процесса"]', 1, 'Когда канал закрыт и пуст, recv() возвращает ошибку и цикл рабочего завершается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 3, 'Зачем передавать «текущее время» параметром в ведро с жетонами?', '["Чтобы оно работало быстрее","Чтобы поведение проверялось тестами без реального ожидания","Это требует std","Чтобы избежать мьютексов"]', 1, 'Детерминированное время — основа тестируемости любого кода с таймерами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 42, 4, 'Чем интеграционный тест сервера полезнее модульных?', '["Он быстрее","Он проверяет систему целиком — реальный сокет, порядок слоёв, заголовки, завершение соединений","Он не нужен","Он заменяет логи"]', 1, 'Такие тесты ловят ошибки на стыках, которых не видно по отдельным функциям.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 43, 'theory', 'Квиз: данные и PostgreSQL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 0, 'Как устроено обычное сообщение протокола PostgreSQL?', '["Строка текста с переводом строки","Метка в один байт, длина (4 байта, включая себя) и содержимое","JSON-объект","Только длина и тело без метки"]', 1, 'Числа передаются старшим байтом вперёд; в DataRow длина −1 означает NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 1, 'Почему значения нельзя подставлять в SQL конкатенацией строк?', '["Это медленно","Возможно внедрение SQL: значение с кавычкой меняет смысл запроса; нужны параметры $1, $2…","Postgres не принимает текст","Из-за кодировки"]', 1, 'Параметры передаются в протоколе отдельно от текста запроса и не интерпретируются как код.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 2, 'Как в Rust естественно выражается колонка, допускающая NULL?', '["Значением по умолчанию","Типом Option<T>","Паникой при чтении","Особой строкой \"NULL\""]', 1, 'Компилятор не позволит забыть обработать отсутствие значения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 3, 'Что делает Drop у охранного объекта транзакции, если не вызывали commit?', '["Ничего","Отправляет ROLLBACK — любая ошибка до commit отменяет изменения","Закрывает соединение","Фиксирует транзакцию"]', 1, 'Откат привязан к области видимости, поэтому его нельзя забыть в какой-то из веток с `?`.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 4, 'Что значит идемпотентность миграций?', '["Миграции нельзя откатывать","Повторный запуск не применяет уже применённые версии и ничего не меняет","Они выполняются параллельно","Они не меняют схему"]', 1, 'Записанные номера применённых версий позволяют безопасно запускать миграции при каждом старте.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 44, 'theory', 'Квиз: axum');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 0, 'Чем является Router в axum с точки зрения tower?', '["Только таблицей путей, не связанной с tower","Сервисом (Service): принимает запрос и асинхронно возвращает ответ","Отдельным потоком","Макросом"]', 1, 'Router реализует tower::Service, поэтому подходят слои, таймауты и вызов напрямую через oneshot.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 1, 'Какой экстрактор допустимо ставить только последним аргументом обработчика?', '["Path","Query","Json — он читает тело запроса, которое потребляется один раз","State"]', 2, 'Тело читается один раз, поэтому экстрактор, потребляющий его, ставят последним.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 2, 'Что вернёт axum на запрос с неподходящим методом к существующему пути?', '["404","405 Method Not Allowed","200 с пустым телом","500"]', 1, 'Путь найден, а метод не зарегистрирован — это 405; 404 — когда не найден путь.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 3, 'Как в axum 0.8 записывается параметр пути?', '["/users/:id","/users/{id}","/users/<id>","/users/$id"]', 1, 'С версии 0.8 используются фигурные скобки; запись с двоеточием больше не поддерживается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 4, 'Как проверить обработчик без запуска сервера и открытия порта?', '["Только запустить сервер на порту 8080","Вызвать Router как Service через tower::ServiceExt::oneshot","Нельзя проверить без браузера","Запустить curl вручную"]', 1, 'oneshot отправляет запрос в роутер в памяти, без сокетов; тело читают через to_bytes.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 45, 'theory', 'Квиз: состояние и слои');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 0, 'Почему внутри состояния axum обычно лежит Arc?', '["Это требование языка Rust","Состояние клонируется на каждый запрос, а Arc клонирует только счётчик ссылок и сохраняет общие данные","Arc ускоряет сеть","Без Arc нельзя использовать async"]', 1, 'State: Clone клонируется на запрос; Arc делает клон дешёвым и разделяет данные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 1, 'Что нельзя делать со std::sync::MutexGuard в async-обработчике?', '["Читать значение","Удерживать его через .await","Использовать в замыкании","Передавать в функцию"]', 1, 'Охранник не Send и блокирует другие задачи; блокировку отпускают до await или берут tokio::sync::Mutex.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 2, 'Какой слой окажется самым внешним при Router::layer(A).layer(B)?', '["A","B — последний добавленный оборачивает всё предыдущее","Они равноправны","Зависит от имён типов"]', 1, 'layer оборачивает всё добавленное до него, поэтому последний слой видит запрос первым.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 3, 'Чем route_layer отличается от layer?', '["Ничем","route_layer применяется только к существующим маршрутам и не затрагивает запросы к несуществующим путям","route_layer быстрее","route_layer только для POST"]', 1, 'layer оборачивает и fallback, route_layer — только найденные маршруты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 45, 4, 'Какой статус возвращает слой ограничения размера тела при превышении лимита?', '["400","408","413","500"]', 2, '413 Payload Too Large; 408 — это таймаут запроса.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 46, 'theory', 'Квиз: serde и ошибки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 0, 'Какой атрибут serde запрещает неизвестные поля в JSON запроса?', '["#[serde(strict)]","#[serde(deny_unknown_fields)]","#[serde(skip_unknown)]","#[serde(no_extra)]"]', 1, 'deny_unknown_fields делает разбор строгим: опечатка в имени поля станет ошибкой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 1, 'Какой статус возвращает Json-экстрактор, если тело — корректный JSON, но поля не подходят по типам?', '["400","415","422","500"]', 2, '422 Unprocessable Entity: синтаксис верен, данные не подходят; 400 — синтаксическая ошибка, 415 — не тот Content-Type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 2, 'Что нельзя показывать клиенту в ответе на внутреннюю ошибку?', '["Общее сообщение","Идентификатор запроса","Текст SQL-запроса, пути на диске и другие подробности","Код статуса"]', 2, 'Подробности пишут в журнал; клиенту — общее сообщение и, возможно, идентификатор запроса.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 3, 'Зачем реализуют From<ошибка_библиотеки> для AppError?', '["Чтобы оператор ? сам преобразовывал ошибки","Чтобы ускорить компиляцию","Чтобы скрыть ошибки","Это требуется для serde"]', 0, '? вызывает From::from при несовпадении типов ошибок, так код остаётся линейным.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 46, 4, 'Как отличить в PATCH отсутствующее поле от явного null?', '["Никак","Option<Option<T>> с подходящим десериализатором","Использовать String","Отправлять два запроса"]', 1, 'Внешний Option — «поле пришло», внутренний — «значение или null».');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 47, 'theory', 'Квиз: PostgreSQL и sqlx');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 0, 'Как правильно передавать значения в SQL-запрос в sqlx?', '["Подставлять через format! в текст запроса","Через параметры $1, $2 и метод bind","Конкатенацией строк","Через переменные окружения"]', 1, 'Привязанные параметры уходят отдельно от текста запроса и не могут быть приняты за команды SQL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 1, 'Что произойдёт с транзакцией sqlx, если объект Transaction уничтожить без commit?', '["Изменения применятся","Изменения откатятся","Программа завершится","Транзакция зависнет навсегда"]', 1, 'Без commit транзакция откатывается при уничтожении — удобно при раннем выходе по ошибке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 2, 'Какой код SQLSTATE означает нарушение уникальности?', '["23503","23505","23514","42P01"]', 1, '23505 — unique_violation; 23503 — внешний ключ, 23514 — проверка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 3, 'Почему не стоит держать соединение пула во время долгой внешней операции?', '["Соединения дорогие, а пул ограничен: несколько медленных операций исчерпают пул","Это запрещено компилятором","База закроет соединение сразу","Это ускоряет запросы"]', 0, 'Размер пула мал; захваченные соединения не дают обслуживать остальные запросы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 4, 'Почему пагинация «сообщения до id N» лучше, чем OFFSET?', '["Она короче в записи","Индекс позволяет сразу перейти к нужному месту, а OFFSET вынужден пропускать строки","OFFSET запрещён в PostgreSQL","Разницы нет"]', 1, 'Выборка по ключу использует индекс и не замедляется с ростом номера страницы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 48, 'theory', 'Квиз: пароли и сессии');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 0, 'Почему пароли не шифруют, а хешируют?', '["Шифрование медленнее","Ключ шифрования утечёт вместе с базой; хеш необратим","Хеши короче","Так проще писать код"]', 1, 'Шифр обратим при наличии ключа; хеш с солью восстановить нельзя, остаётся только перебор.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 1, 'Зачем добавляют соль к паролю перед хешированием?', '["Чтобы одинаковые пароли давали разные хеши и не работали готовые таблицы","Чтобы ускорить проверку","Чтобы пароль стал короче","Соль — это секретный ключ сервера"]', 0, 'Соль случайна и хранится рядом с хешем; она не секрет, но портит атаки по заранее вычисленным таблицам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 2, 'Что должен вернуть вход для неизвестного имени и для неверного пароля?', '["Разные тексты ошибок","Одинаковый ответ 401 с одним и тем же текстом","404 для неизвестного имени","500"]', 1, 'Разные ответы раскрывают, какие имена существуют (перечисление пользователей).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 3, 'Что хранится в таблице сессий вместо самого токена?', '["Пароль пользователя","Хеш токена","Соль","Ничего"]', 1, 'Тогда утечка таблицы не даёт готовых токенов; токен случайный, быстрый хеш для него достаточен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 48, 4, 'Какой код означает «личность известна, но действие запрещено»?', '["401","403","404","409"]', 1, '401 — не аутентифицирован; 403 — аутентифицирован, но прав нет.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 49, 'theory', 'Квиз: API комнат и сообщений');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 0, 'Какой метод подходит для идемпотентного «вступить в комнату»?', '["POST","PUT на /rooms/{id}/members/me — повтор не меняет результат","GET","PATCH без тела"]', 1, 'PUT задаёт состояние «я участник»: повторный вызов даёт тот же результат.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 1, 'Как считать длину текста сообщения?', '["В байтах","В символах (chars)","В словах","Не ограничивать"]', 1, 'Кириллица в UTF-8 — два байта на букву; ограничение в байтах несправедливо к не-латинскому тексту.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 2, 'Зачем нужен ключ идемпотентности при отправке сообщения?', '["Чтобы шифровать текст","Чтобы повтор той же отправки не создавал дубликат","Чтобы ускорить вставку","Чтобы упорядочить сообщения"]', 1, 'Если ответ потерялся, клиент повторяет запрос; уникальный ключ превращает повтор в безвредную операцию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 3, 'Почему курсорная пагинация (до id N) лучше номера страницы?', '["Она проще для чтения","Не замедляется на глубоких страницах и не «съезжает» при появлении новых сообщений","Она запрещает новые сообщения","Разницы нет"]', 1, 'Курсор использует индекс; новые сообщения сверху не сдвигают уже прочитанное.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 4, 'Что должен ответить сервер не-участнику на запрос к закрытой комнате?', '["403 Forbidden","То же, что на несуществующую комнату: 404","200 с пустым списком","500"]', 1, 'Иначе по различию ответов можно узнать, какие закрытые комнаты существуют.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 50, 'theory', 'Квиз: веб-сокеты и рассылка');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 0, 'Каким кодом сервер отвечает на успешный Upgrade до WebSocket?', '["200 OK","101 Switching Protocols","204 No Content","301 Moved"]', 1, '101 означает переход на другой протокол; дальше по тому же соединению идут кадры WebSocket.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 1, 'Почему сокет разделяют на приёмник и передатчик и запускают две задачи?', '["Это быстрее","Чтение команд и отправка событий — независимые активности, их нельзя блокировать друг другом","Так требует протокол","Чтобы шифровать трафик"]', 1, 'Одна задача ждёт сообщений клиента, другая — событий из канала; завершение любой должно останавливать обе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 2, 'Что получает приёмник broadcast-канала, если слишком отстал?', '["Паникует программа","Ошибку Lagged с числом пропущенных сообщений","Все сообщения заново","Канал закрывается"]', 1, 'Старые события вытесняются; клиент узнаёт о потере и должен догнать историю запросом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 3, 'В каком порядке выполнять запись и рассылку нового сообщения?', '["Сначала рассылка, потом запись","Сначала запись в базу (получить id), потом рассылка","Параллельно без порядка","Только рассылка"]', 1, 'Клиент, получивший событие, всегда найдёт сообщение в истории; рассылка — быстрый путь, база — источник правды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 50, 4, 'Как узнать, что пользователь офлайн, если у него несколько соединений?', '["По последнему сообщению","Счётчик его активных соединений дошёл до нуля","По IP-адресу","Никак"]', 1, 'Присутствие считают по числу активных соединений пользователя.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 51, 'theory', 'Квиз: эксплуатация сервиса');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 0, 'Почему при старте лучше проверять конфигурацию целиком и сразу?', '["Это быстрее","Ошибка станет видна сразу и понятно, а не через час работы","Это требует компилятор","Так меньше кода"]', 1, 'Принцип fail fast: неверные настройки не должны прятаться до момента первого использования.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 1, 'Что должен проверять эндпоинт /ready, в отличие от /health?', '["Только что процесс жив","Доступность зависимостей: базы данных и т. п.","Версию компилятора","Ничего"]', 1, '/health не зависит от внешних систем, /ready отвечает 503, пока сервис не может обслуживать трафик.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 2, 'Каков правильный порядок корректной остановки сервиса?', '["Закрыть пул, потом принимать запросы","Перестать принимать новые, дождаться текущих, закрыть соединения и пул","Сразу exit()","Закрыть только сокет"]', 1, 'Так не теряются запросы, выполняющиеся в момент сигнала.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 3, 'Зачем нужны таймаут получения соединения из пула и таймаут запроса к базе?', '["Для красоты логов","Чтобы сбой превращался в быстрый понятный отказ, а не в бесконечное ожидание","Чтобы ускорить базу","Это обязательно для Docker"]', 1, 'Без ограничений ожидания очереди растут и сервис «зависает».');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 51, 4, 'Как безопасно менять схему базы без простоя?', '["Удалить столбец и сразу выложить новый код","Двумя шагами: расширить (совместимо) и только потом сузить","Остановить все серверы","Менять схему вручную в рабочей базе"]', 1, 'Старые и новые экземпляры работают одновременно, поэтому сначала добавляют, потом переключают, потом удаляют.');
